def get_dataset_distance_range(dataset, sample_size=500, buffer_ratio=0.1):
    """Dynamically determine physical min and max distance from dataset."""
    sample_indices = range(min(sample_size, len(dataset)))
    min_dist = float('inf')
    max_dist = 0.0
    for idx in sample_indices:
        pos = dataset[idx].pos
        dists = torch.cdist(pos, pos)
        dists = dists[dists > 0]
        if len(dists) > 0:
            min_dist = min(min_dist, dists.min().item())
            max_dist = max(max_dist, dists.max().item())
    r_start = max(0.0, round(min_dist * (1.0 - buffer_ratio), 2))
    r_end = round(max_dist * (1.0 + buffer_ratio), 2)
    return r_start, r_end

r_start, r_end = get_dataset_distance_range(dataset)
print(f"Dynamically calibrated RBF distance range: start={r_start:.2f} Å, end={r_end:.2f} Å")

